/*
 * The FatturaPA structure check: does the document have the shape the XML schema of the Italian electronic invoice gives it (the elements it allows, in its order,
 * as often as it allows, with values and attributes of the right kind)? The Sistema di Interscambio runs this schema check first (error 00200 when the file does
 * not conform to the schema); the business controls come after it.
 *
 * The content model is data (it-schema-data.js, generated by tests/gen-it-schema.py from the schema); this file walks the document with it.
 * Its answers are compared with libxml2's XML Schema validation on mutated documents (tests/it-xsd-differential.js).
 */
(function () {
  "use strict";
  const S = window.IT_SCHEMA;
  const DSIG = "http://www.w3.org/2000/09/xmldsig#";
  const XSI = "http://www.w3.org/2001/XMLSchema-instance", XMLNS = "http://www.w3.org/2000/xmlns/";
  const keyOf = (el) => (el.namespaceURI || "") + "|" + el.localName;
  // the schema declares the root in its namespace and every element below it in no namespace (elementFormDefault is unqualified); the signature is in the XMLDSig namespace
  const nameOf = (el) => el.namespaceURI === DSIG ? "ds:" + el.localName : el.namespaceURI ? "{" + el.namespaceURI + "}" + el.localName : el.localName;

  // ---- XML Schema regular expressions -> JavaScript (the patterns are anchored; \p{IsBasicLatin} and \p{IsLatin-1Supplement} are character blocks)
  const reCache = {};
  const regex = (p) => reCache[p] || (reCache[p] = new RegExp("^(?:" + p.replace(/\\p\{IsBasicLatin\}/g, "\\u0000-\\u007F").replace(/\\p\{IsLatin-1Supplement\}/g, "\\u0080-\\u00FF").replace(/\(\?!/g, "(?!") + ")$"));
  // the Latin blocks sit inside [ ] in the schema, or alone ( \p{..}{1,10} ) outside of one: outside they must become a class
  const fixOutside = (p) => p.replace(/(^|[^\[\\])\\p\{IsBasicLatin\}/g, "$1[\\u0000-\\u007F]");
  const re = (p) => regex(fixOutside(p));

  // ---- the lexical forms of the XML Schema types the schema uses
  const TZ = "(?:Z|[+-](?:0\\d|1[0-3]):[0-5]\\d|[+-]14:00)?";
  const DATE = "-?\\d{4,}-\\d\\d-\\d\\d", TIME = "(?:[01]\\d|2[0-3]):[0-5]\\d:[0-5]\\d(?:\\.\\d+)?|24:00:00(?:\\.0+)?";
  const realDate = (s) => {
    const m = /^(-?\d{4,})-(\d\d)-(\d\d)/.exec(s);
    if (!m) return false;
    const y = Math.abs(+m[1]), mo = +m[2], d = +m[3];
    if (y === 0 || mo < 1 || mo > 12 || d < 1) return false;
    const leap = (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
    return d <= [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][mo - 1];
  };
  const LEX = {
    decimal: { re: /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/, what: "decimal number" },
    integer: { re: /^[+-]?\d+$/, what: "whole number" },
    date: { re: new RegExp("^" + DATE + TZ + "$"), ok: realDate, what: "date (YYYY-MM-DD)" },
    dateTime: { re: new RegExp("^" + DATE + "T(?:" + TIME + ")" + TZ + "$"), ok: realDate, what: "date and time" },
    base64Binary: { re: /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/, strip: true, what: "base64 data" }
  };
  const num = (s) => parseFloat(s);
  // the value as the type reads it: string keeps its white space, normalizedString turns tab and line breaks into spaces, token and the types with whiteSpace collapse also trim
  function normalised(v, text) {
    const ws = v.ws || (v.b === "token" ? "collapse" : v.b === "string" ? "preserve" : v.b === "normalizedString" ? "replace" : "collapse");
    if (ws === "preserve") return text;
    const r = text.replace(/[\t\r\n]/g, " ");
    return ws === "replace" ? r : r.replace(/ +/g, " ").trim();
  }
  // returns "" when the text fits the type, else [kind, what]: kind "04" form of the base type, "07" list of values, "08" format, length or range
  function valueProblem(v, text) {
    const t = v.b === "base64Binary" ? text.replace(/[\t\r\n ]+/g, "") : normalised(v, text);
    const L = LEX[v.b];
    if (L && !(L.re.test(t) && (!L.ok || L.ok(t)))) return ["04", L.what];
    if (v.e && v.e.indexOf(t) < 0) return ["07", ""];
    const len = Array.from(t).length;
    if (v.len != null && len !== v.len) return ["08", "exactly " + v.len + " characters"];
    if (v.min != null && len < v.min) return ["08", "at least " + v.min + " characters"];
    if (v.max != null && len > v.max) return ["08", "at most " + v.max + " characters"];
    if (v.p) for (const level of v.p) if (!level.some((p) => re(p).test(t))) return ["08", "the format the schema gives"];
    if (v.lo != null && (L && L.re ? (v.b === "date" ? t < v.lo : num(t) < num(v.lo)) : false)) return ["08", "not before " + v.lo];
    if (v.hi != null && (L && L.re ? (v.b === "date" ? t > v.hi : num(t) > num(v.hi)) : false)) return ["08", "not above " + v.hi];
    return "";
  }

  // ---- walking the document
  function check(root) {
    const found = [];    // { kind, el, detail }
    const add = (kind, el, detail) => found.push({ kind, el, detail });
    const rootType = S.roots[keyOf(root)];
    if (!rootType) return found;
    const qkey = (name) => S.ns + "|" + name;

    // the names of the elements a model can start with
    const firsts = (m) => m[0] === "e" ? [m[1]] : m[0] === "x" ? ["ds:Signature"] : m[0] === "s" ? (m[1].length ? firsts(m[1][0]) : []) : [].concat(...m[1].map(firsts));
    const names = (m, out) => { if (m[0] === "e") out.add(m[1]); else if (m[0] === "x") out.add("ds:Signature"); else m[1].forEach((k) => names(k, out)); return out; };
    const kidName = (c) => nameOf(c);

    function walk(el, tid, hasDefault) {
      const T = S.types[tid];
      attributes(el, T);
      const kids = Array.from(el.children);
      if (T.v) {
        if (kids.length) add("06", el, nameOf(el) + " holds a value only, but contains the element " + nameOf(kids[0]));
        const p = hasDefault && el.textContent === "" ? "" : valueProblem(T.v, el.textContent);
        if (p) problem(el, el.textContent, p);
        return;
      }
      for (const n of Array.from(el.childNodes)) if (n.nodeType === 3 && /\S/.test(n.nodeValue)) { add("06", el, nameOf(el) + " contains text, but only elements are allowed"); break; }
      const missing = [];     // [name, text]
      let i = 0;
      // consumes the children from i on as the model m allows; returns how many times m matched
      function run(m) {
        const kind = m[0];
        if (kind === "e" || kind === "x") {
          const [, name, t, mn, mx, def] = kind === "e" ? m : [0, m[1], null, m[2], m[3]];
          let count = 0;
          while (i < kids.length && kidName(kids[i]) === name && (mx < 0 || count < mx)) {
            if (kind === "e") walk(kids[i], t, def);
            i++; count++;
          }
          if (count < mn) missing.push([name, nameOf(el) + " needs " + name]);
          return count;
        }
        const mn = m[2], mx = m[3];
        let count = 0;
        while (mx < 0 || count < mx) {
          const start = i;
          if (kind === "s") {
            if (count >= mn && !(i < kids.length && firsts(m).indexOf(kidName(kids[i])) >= 0)) break;
            const before = missing.length;
            m[1].forEach(run);
            if (i === start && count >= mn) { missing.length = before; break; }
          } else {
            const alt = i < kids.length ? m[1].find((a) => firsts(a).indexOf(kidName(kids[i])) >= 0) : null;
            if (!alt) { if (count < mn) missing.push([m[1].map((a) => firsts(a)[0]).join("|"), nameOf(el) + " needs one of " + m[1].map((a) => firsts(a).join(" and ")).join(" / ")]); break; }
            run(alt);
          }
          count++;
          if (i === start) break;
        }
        return count;
      }
      run(T.m);
      const leftover = kids.slice(i), known = names(T.m, new Set());
      leftover.forEach((c, k) => {
        const idx = i + k, key = kidName(c);
        if (!known.has(key)) { add("01", c, nameOf(c) + " is not allowed in " + nameOf(el)); return; }
        if (idx > 0 && kidName(kids[idx - 1]) === key) add("03", c, nameOf(c) + " occurs more often than the schema allows in " + nameOf(el));
        else add("01", c, nameOf(c) + " comes in the wrong place in " + nameOf(el));
      });
      missing.forEach(([name, text]) => { if (!leftover.some((c) => name.split("|").indexOf(kidName(c)) >= 0)) add("02", el, text); });
    }

    function problem(el, text, p) {
      const shown = text.trim().slice(0, 40);
      if (p[0] === "07") add("07", el, nameOf(el) + ": “" + shown + "” is not one of the values the schema allows");
      else add(p[0], el, nameOf(el) + ": “" + shown + "” does not fit the type: " + p[1]);
    }

    function attributes(el, T) {
      const allowed = T.a || {};
      for (const a of Array.from(el.attributes)) {
        if (a.namespaceURI === XMLNS || a.namespaceURI === XSI || a.name === "xmlns" || a.name.startsWith("xmlns:")) continue;
        if (a.namespaceURI || !(a.name in allowed)) { add("05", el, nameOf(el) + " has the attribute " + a.name + ", which the schema does not allow there"); continue; }
        const p = valueProblem(S.types[allowed[a.name][0]].v, a.value);
        if (p) problem(el, a.value, p);
      }
      Object.keys(allowed).forEach((n) => { if (allowed[n][1] && !el.hasAttribute(n)) add("05", el, nameOf(el) + " needs the attribute " + n); });
    }

    walk(root, rootType);
    return found;
  }

  const RULES = [
    ["01", "Every element must be one that the schema allows at that place, in the order the schema gives"],
    ["02", "Every element that the schema requires must be present"],
    ["03", "No element may occur more often than the schema allows"],
    ["04", "Every value must have the form of its type (number, date …)"],
    ["05", "Every attribute the schema requires must be present, and no other attribute may be used"],
    ["06", "An element holds either a value or other elements, never both"],
    ["07", "Every coded value must be one of the values the schema lists"],
    ["08", "Every value must have the format, length and range the schema gives"]
  ];
  // reports one result per kind of problem, passing or failing, with the elements that fail
  function report(root, rule) {
    const found = check(root);
    RULES.forEach(([n, text]) => {
      const mine = found.filter((f) => f.kind === n);
      rule("IT-XSD-" + n, mine.length ? mine.map((f) => f.el) : root, !mine.length, text, mine.length ? mine[0].detail : "");
    });
  }
  window.ItSchema = { check, report, rules: RULES.map((r) => "IT-XSD-" + r[0]), texts: RULES };
})();
